PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, key_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','player')), disabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE login_limits (bucket TEXT PRIMARY KEY, attempts INTEGER NOT NULL, resets_at INTEGER NOT NULL);
CREATE TABLE squads (id TEXT PRIMARY KEY, name TEXT NOT NULL, region TEXT NOT NULL DEFAULT 'eu' CHECK(region='eu'), ruleset TEXT NOT NULL CHECK(ruleset IN ('normal','pvp','roleplay')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE characters (id TEXT PRIMARY KEY, name TEXT NOT NULL, normalized_name TEXT NOT NULL, region TEXT NOT NULL DEFAULT 'eu' CHECK(region='eu'), ruleset TEXT NOT NULL CHECK(ruleset IN ('normal','pvp','roleplay')), owner_id TEXT REFERENCES users(id) ON DELETE SET NULL, verified INTEGER NOT NULL DEFAULT 0, provider TEXT, external_id TEXT, profile_json TEXT NOT NULL DEFAULT '{}', sync_status TEXT NOT NULL DEFAULT 'idle', sync_error TEXT, last_synced_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(verified=0 OR (provider IS NOT NULL AND external_id IS NOT NULL)));
CREATE UNIQUE INDEX placeholder_identity ON characters(region,ruleset,normalized_name) WHERE verified=0;
CREATE UNIQUE INDEX verified_identity ON characters(provider,region,ruleset,external_id) WHERE verified=1;
CREATE TRIGGER character_limit BEFORE INSERT ON characters WHEN (SELECT COUNT(*) FROM characters)>=50 BEGIN SELECT RAISE(ABORT,'Maximum of 50 stored characters reached'); END;
CREATE TABLE squad_characters (squad_id TEXT NOT NULL REFERENCES squads(id) ON DELETE CASCADE, character_id TEXT NOT NULL REFERENCES characters(id) ON DELETE CASCADE, PRIMARY KEY(squad_id,character_id));
CREATE TRIGGER membership_ruleset BEFORE INSERT ON squad_characters WHEN (SELECT ruleset FROM squads WHERE id=NEW.squad_id)!=(SELECT ruleset FROM characters WHERE id=NEW.character_id) BEGIN SELECT RAISE(ABORT,'Character and squad rulesets must match'); END;
CREATE TABLE wishlist_entries (id TEXT PRIMARY KEY, character_id TEXT NOT NULL REFERENCES characters(id) ON DELETE CASCADE, category TEXT NOT NULL CHECK(category IN ('item','enchant','recipe','other')), priority TEXT NOT NULL CHECK(priority IN ('high','normal','low')), status TEXT NOT NULL CHECK(status IN ('wanted','acquired')), title TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', source_url TEXT, catalog_ref TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX wishlist_character ON wishlist_entries(character_id);
CREATE TABLE game_cache (cache_key TEXT PRIMARY KEY, kind TEXT NOT NULL, region TEXT NOT NULL DEFAULT 'eu', ruleset TEXT, value_json TEXT NOT NULL, fetched_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE acquisition_sources (id TEXT PRIMARY KEY, catalog_ref TEXT NOT NULL, label TEXT NOT NULL, source_url TEXT, details_json TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL);
CREATE TABLE provider_state (provider TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TRIGGER rotate_invalidates_sessions AFTER UPDATE OF key_hash ON users WHEN NEW.key_hash != OLD.key_hash BEGIN DELETE FROM sessions WHERE user_id=NEW.id; END;
CREATE TRIGGER disable_invalidates_sessions AFTER UPDATE OF disabled ON users WHEN NEW.disabled != 0 BEGIN DELETE FROM sessions WHERE user_id=NEW.id; END;
